"use strict";

/**
 * The branded letterhead shared by every generated document, in each format:
 * crest + school name + address/contact, the document title, a facts box
 * (filters, class, session ...) and a "generated by / at" footer. Layout and
 * colours follow the result documents (see `utils/branding.js`).
 *
 *   brand: the object from `schoolBranding()`
 *   facts: [[label, value]]   a "Note" fact is printed in full under the box
 */
const { rgb } = require("./branding");

const WHITE = [1, 1, 1];

// ---- PDF -----------------------------------------------------------------

/** Letterhead at the top of the current page; leaves `doc.y` below it. */
function pdfHeader(doc, brand, { title, facts: allFacts = [], factsPerRow = 4 }) {
  const facts = allFacts.filter(([label]) => label !== "Note");
  const notes = allFacts.filter(([label]) => label === "Note").map(([, value]) => String(value));
  const c = brand.colors;
  const m = doc.margin;
  const usable = doc.width - m * 2;
  const logo = 46;
  doc.image(brand.logo, m, m, logo, logo);
  const left = m + logo + 10;
  const titleW = Math.min(230, usable * 0.38);
  const nameW = usable - logo - 10 - titleW - 8;
  doc.text(left, m + 16, brand.name, { size: 15, bold: true, color: rgb(c.brandDeep), width: nameW });
  if (brand.address) doc.text(left, m + 29, brand.address, { size: 8, color: rgb(c.muted), width: nameW });
  if (brand.contact) doc.text(left, m + 40, brand.contact, { size: 8, color: rgb(c.muted), width: nameW });
  doc.text(m + usable - titleW, m + 18, title, { size: 12, bold: true, color: rgb(c.brand), width: titleW, align: "right" });
  doc.line(m, m + logo + 6, m + usable, m + logo + 6, { width: 2, color: rgb(c.brand) });
  doc.y = m + logo + 14;

  if (facts.length) {
    const rows = Math.ceil(facts.length / factsPerRow);
    const cellW = usable / factsPerRow;
    const boxH = rows * 24 + 6;
    doc.rect(m, doc.y, usable, boxH, { fill: rgb(c.brandWash), stroke: rgb(c.brandLine), width: 0.7 });
    facts.forEach(([label, value], i) => {
      const x = m + (i % factsPerRow) * cellW + 8;
      const y = doc.y + Math.floor(i / factsPerRow) * 24;
      doc.text(x, y + 12, String(label).toUpperCase(), { size: 6.5, bold: true, color: rgb(c.muted), width: cellW - 14 });
      doc.text(x, y + 23, value == null || value === "" ? "-" : String(value), { size: 9, bold: true, color: rgb(c.ink), width: cellW - 14 });
    });
    doc.y += boxH + 10;
  }
  for (const note of notes) {
    doc.text(m, doc.y + 4, `Note: ${note}`, { size: 7.5, color: rgb(c.muted), width: usable });
    doc.y += 13;
  }
  if (notes.length) doc.y += 4;
  return doc;
}

/** Footer on every page: who generated it and when, and "Page n of N". */
function pdfFooter(doc, brand) {
  const c = brand.colors;
  const m = doc.margin;
  const usable = doc.width - m * 2;
  const lineY = doc.height - m + 4;
  const y = doc.height - m / 2 - 2;
  const by = brand.generatedBy ? `Generated by ${brand.generatedBy} on ${brand.generatedAt}` : `Generated on ${brand.generatedAt}`;
  return doc.eachPage((page, count) => {
    doc.line(m, lineY, m + usable, lineY, { width: 0.5, color: rgb(c.line) });
    doc.text(m, y, `${brand.name}  |  ${by}`, { size: 7, color: rgb(c.muted), width: usable - 70 });
    doc.text(m, y, `Page ${page} of ${count}`, { size: 7, color: rgb(c.muted), width: usable, align: "right" });
  });
}

/** Options for `PdfDoc.table` that give it the brand header row. */
function pdfTableStyle(brand) {
  return { headerFill: rgb(brand.colors.brand), headerColor: WHITE, lineColor: rgb(brand.colors.line) };
}

// ---- XLSX (exceljs) ------------------------------------------------------

const argb = (hex) => `FF${hex}`;

/**
 * Writes the letterhead into rows 1.. of an exceljs worksheet and returns the
 * next free row number. The crest floats over the first rows.
 */
function xlsxHeader(book, sheet, brand, { title, facts = [], span = 6 }) {
  const c = brand.colors;
  const image = book.addImage({ buffer: brand.logo, extension: "jpeg" });
  sheet.addImage(image, { tl: { col: 0.1, row: 0.15 }, ext: { width: 58, height: 58 }, editAs: "oneCell" });
  const line = (rowNo, value, font, height) => {
    const row = sheet.getRow(rowNo);
    row.getCell(1).value = value;
    row.getCell(1).font = font;
    row.getCell(1).alignment = { indent: 9, vertical: "middle" };
    if (height) row.height = height;
  };
  line(1, brand.name, { bold: true, size: 16, color: { argb: argb(c.brandDeep) } }, 26);
  line(2, brand.address, { size: 9, color: { argb: argb(c.muted) } });
  line(3, brand.contact, { size: 9, color: { argb: argb(c.muted) } });
  line(4, title, { bold: true, size: 13, color: { argb: argb(c.brand) } }, 20);
  for (let col = 1; col <= span; col += 1) {
    sheet.getRow(4).getCell(col).border = { bottom: { style: "medium", color: { argb: argb(c.brand) } } };
  }
  let rowNo = 5;
  const allFacts = [...facts, ["Generated by", brand.generatedBy], ["Generated at", brand.generatedAt]].filter(([, v]) => v != null && v !== "");
  for (const [label, value] of allFacts) {
    const row = sheet.getRow(rowNo);
    row.getCell(1).value = `${label}: ${value}`;
    row.getCell(1).font = { size: 9, color: { argb: argb(c.ink) } };
    for (let col = 1; col <= span; col += 1) {
      row.getCell(col).fill = { type: "pattern", pattern: "solid", fgColor: { argb: argb(c.brandWash) } };
    }
    rowNo += 1;
  }
  return rowNo + 1;
}

/** Brand-green header row with white bold text. */
function xlsxHeadRow(row, brand) {
  row.eachCell((cell) => {
    cell.font = { bold: true, color: { argb: "FFFFFFFF" } };
    cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: argb(brand.colors.brand) } };
    cell.alignment = { vertical: "middle", wrapText: true };
    cell.border = { bottom: { style: "thin", color: { argb: argb(brand.colors.brandDeep) } } };
  });
  row.height = 20;
}

// ---- CSV -----------------------------------------------------------------

/**
 * "key,value" lines before the table: school, report title, filters and the
 * generation stamp, then a blank line. Every line has exactly two fields so a
 * parser can skip to the first blank line to reach the table header.
 */
function csvPreamble(brand, { title, facts = [] }) {
  return [
    ["School", brand.name],
    ["Report", title],
    ...facts,
    ["Generated by", brand.generatedBy],
    ["Generated at", brand.generatedAt],
    [],
  ];
}

module.exports = { pdfHeader, pdfFooter, pdfTableStyle, xlsxHeader, xlsxHeadRow, csvPreamble };
